/// String of characters with support for escaped invalid-XML characters. For all characters which cannot be represented in XML as defined by the XML 1.0 specification, the characters are escaped using the Unicode numerical character representation escape character format _xHHHH_, where H represents a hexadecimal character in the character's value. \[Example: The Unicode character 8 is not permitted in an XML 1.0 document, so it must be escaped as _x0008_. end example\]
///
/// Schema type `ST_Xstring`.
pub type ST_Xstring = String;

/// Vertical Alignment Location (ECMA-376 Part 1 §22.9.2.20).
///
/// This simple type specifies the set of possible relative vertical positions for the parent floating object. This relative position is specified relative to the vertical anchor specified by the parent object.
///
/// Schema type `ST_YAlign`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub enum ST_YAlign {
    /// `inline`: In line With Text — Specifies that the parent object shall be vertically aligned in line with the surrounding text (i.e. shall not allow any text wrapping around it when positioned in the document.
    #[default]
    Inline,
    /// `top`: Top — Specifies that the parent object shall be vertically aligned to the top edge of the anchor object .
    Top,
    /// `center`: Centered Vertically — Specifies that the parent object shall be vertically centered with respect to the anchor object.
    Center,
    /// `bottom`: Bottom — Specifies that the parent object shall be vertically aligned to the bottom edge of the anchor object.
    Bottom,
    /// `inside`: Inside Anchor Extents — Specifies that the parent object shall be vertically aligned to the edge of the anchor object, and positioned inside that object.
    Inside,
    /// `outside`: Outside Anchor Extents — Specifies that the parent object shall be vertically aligned to the edge of the anchor object, and positioned outside that object.
    Outside,
}
impl ST_YAlign {
    /// All values in schema order.
    pub const ALL: &'static [Self] = &[
        Self::Inline,
        Self::Top,
        Self::Center,
        Self::Bottom,
        Self::Inside,
        Self::Outside,
    ];
    /// The lexical (XML) form of the value.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Inline => "inline",
            Self::Top => "top",
            Self::Center => "center",
            Self::Bottom => "bottom",
            Self::Inside => "inside",
            Self::Outside => "outside",
        }
    }
}
impl XmlValue for ST_YAlign {
    fn parse_xml(s: &str) -> Option<Self> {
        Some(match s.trim() {
            "inline" => Self::Inline,
            "top" => Self::Top,
            "center" => Self::Center,
            "bottom" => Self::Bottom,
            "inside" => Self::Inside,
            "outside" => Self::Outside,
            _ => return None,
        })
    }
    fn write_xml(&self, out: &mut String) {
        out.push_str(self.as_str());
    }
}
impl std::fmt::Display for ST_YAlign {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}
